// Generated by `npx @polishd/next init`, then edited for the demo.
// The dashboard's own stylesheet. Self-contained and scoped to
// .polishd-root, so it needs no Tailwind in this app and cannot
// affect anything outside the dashboard.
import "@polishd/next/dashboard.css";
import { createPolishdPage } from "@polishd/next/dashboard";

// What the site is, its repository and its model: defaults the dashboard
// opens with, which anything saved in the dashboard overrides. Committed,
// so never put a key in it.
import defaults from "../../polishd.defaults.json";

// The dashboard's metadata, which keeps /polishd out of search engines.
export { metadata } from "@polishd/next/dashboard";

// Next requires these to be declared inline in the page module.
export const runtime = "nodejs";
export const dynamic = "force-dynamic";
// Server actions inherit this page's time limit; 300s gives the AI
// analyses headroom on hosts with strict function limits.
export const maxDuration = 300;

// A real app protects this page with POLISHD_DASHBOARD_TOKEN or its own
// auth: the dashboard can change the model settings and spend the model key.
// This is a demo, so anyone may look — and in production nobody may change
// anything. Every server action re-runs this check and arrives with a
// `next-action` header; refusing those leaves the dashboard readable and
// read-only. `proxy.ts` refuses the same requests a layer earlier.
// In development the dashboard is yours: connect a model, run the reviews.
const READ_ONLY = process.env.NODE_ENV === "production";

export default createPolishdPage({
  defaults,
  authenticate: ({ headers }) => !READ_ONLY || !headers.has("next-action"),
});
